import sys

sys.setrecursionlimit(20000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def solve(node):
    if not node:
        return (0, 0)

    left_inc, left_exc = solve(node.left)
    right_inc, right_exc = solve(node.right)

    inc = node.val + left_exc + right_exc
    exc = max(left_inc, left_exc) + max(right_inc, right_exc)

    return (inc, exc)

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    n = int(lines[0].strip())
    if n == 0:
        print(0)
        return

    nodes = {}
    for line in lines[1:n+1]:
        parts = line.strip().split()
        val = int(parts[0])
        nodes[val] = Node(val)
        if len(parts) > 1:
            nodes[val].left = int(parts[1]) if parts[1] != 'null' else None
        if len(parts) > 2:
            nodes[val].right = int(parts[2]) if parts[2] != 'null' else None

    root_val = int(lines[n+1].strip())
    root = nodes[root_val]

    if not root:
        print(0)
        return

    for key, node in nodes.items():
        if node.left is not None and isinstance(node.left, int):
            node.left = nodes[node.left]
        if node.right is not None and isinstance(node.right, int):
            node.right = nodes[node.right]

    inc, exc = solve(root)
    print(max(inc, exc))

if __name__ == "__main__":
    main()
